import{_ as t,c as o,o as n,a2 as r}from"./chunks/framework.FA50ykuN.js";const a="/pr-preview/pr-793/assets/nextgen-public-hosted-zone.D_XBSIWT.svg",s="/pr-preview/pr-793/assets/nextgen-private-hosted-zone.CKJV76tS.svg",i="/pr-preview/pr-793/assets/old-architecture.BKMRWZHF.svg",l="/pr-preview/pr-793/assets/new-architecture.xGlrAtMZ.svg",v=JSON.parse('{"title":"Migration Nextgeneration","description":"","frontmatter":{"github_repo":"https://github.com/gardener/gardener-extension-shoot-dns-service","github_subdir":"docs/development","params":{"github_branch":"master"},"path_base_for_github_subdir":{"from":"content/docs/extensions/others/gardener-extension-shoot-dns-service/migration-nextgeneration.md","to":"migration-nextgeneration.md"},"persona":"Developers","title":"Migration Nextgeneration","prev":false,"next":false},"headers":[],"relativePath":"docs/extensions/others/gardener-extension-shoot-dns-service/migration-nextgeneration/index.md","filePath":"docs/extensions/others/gardener-extension-shoot-dns-service/migration-nextgeneration.md","lastUpdated":null}'),c={name:"docs/extensions/others/gardener-extension-shoot-dns-service/migration-nextgeneration/index.md"};function d(h,e,g,u,m,p){return n(),o("div",null,e[0]||(e[0]=[r('<h1 id="migration-of-dns-controller-manager-to-next-generation" tabindex="-1">Migration of <code>dns-controller-manager</code> to Next Generation <a class="header-anchor" href="#migration-of-dns-controller-manager-to-next-generation" aria-label="Permalink to &quot;Migration of `dns-controller-manager` to Next Generation&quot;">​</a></h1><p>This document outlines the steps taken to migrate to the next generation of <code>dns-controller-manager</code> from <a href="https://github.com/gardener/external-dns-management" target="_blank" rel="noreferrer">external-dns-management</a>.</p><h2 id="architecture-changes" tabindex="-1">Architecture Changes <a class="header-anchor" href="#architecture-changes" aria-label="Permalink to &quot;Architecture Changes&quot;">​</a></h2><p>The <code>nextgeneration</code> DNS controller manager makes now use of the authoritative DNS servers for looking up the current state of DNS record whenever possible. This is a significant change from the previous implementation, which relied on cached data and periodic synchronization to avoid running into rate limits imposed by DNS providers.</p><p>In the standard use case of public hosted zones, the next generation controller queries the authoritative DNS servers directly to determine the existing DNS records.</p><img src="'+a+'" alt="Handling of public hosted zone with nextgeneration" width="300"><p>If the authoritative DNS servers are not accessible (e.g., for private hosted zones), the next generation controller falls back to using the provider&#39;s API to fetch the current state of DNS records.</p><img src="'+s+'" alt="Handling of private hosted zone with nextgeneration" width="300"><p>It also allows to make far-reaching simplifications to the overall architecture of the DNS controller manager and its deployment.</p><p>There is no longer a need for separate caching layers in the form of a seed-wide <code>dns-controller-manager</code> and the <code>Central DNS proxy</code> to avoid high load by the periodic synchronization. Instead, for reading the current state of DNS records, the next generation controller directly queries the authoritative DNS servers or falls back to the provider&#39;s API if necessary.</p><h3 id="old-architecture" tabindex="-1">Old Architecture <a class="header-anchor" href="#old-architecture" aria-label="Permalink to &quot;Old Architecture&quot;">​</a></h3><img src="'+i+'" alt="Old Architecture" width="500"><h4 id="dns-controller-manager-in-shoot-dns-service-extension-namespace" tabindex="-1">DNS Controller Manager in shoot-dns-service extension namespace <a class="header-anchor" href="#dns-controller-manager-in-shoot-dns-service-extension-namespace" aria-label="Permalink to &quot;DNS Controller Manager in shoot-dns-service extension namespace&quot;">​</a></h4><ul><li>Manages DNSProviders and DNSEntries for all control planes (and all other namespades)</li><li>DNSProvider with same credentials map to same &quot;account&quot;</li><li>Complete zone state is cached and synchronised periodically</li><li>batches if supported by handler (but only per namespace = group)</li><li>uses zone reconciliations</li></ul><h4 id="dns-controller-manager-in-control-plane-shoot-dns-service-deployment" tabindex="-1">DNS Controller Manager in control plane (&quot;shoot-dns-service&quot; deployment) <a class="header-anchor" href="#dns-controller-manager-in-control-plane-shoot-dns-service-deployment" aria-label="Permalink to &quot;DNS Controller Manager in control plane (&quot;shoot-dns-service&quot; deployment)&quot;">​</a></h4><ul><li>watches shoot cluster for annotated source objects, DNSEntries</li><li>manages &quot;slave&quot; DNSEntries in control plane namespace</li><li>if enabled, may replicate DNSProviders from shoot cluster to control plane namespace</li><li>does NOT communicate with providers</li></ul><h4 id="dns-central-proxy-in-garden-runtime-cluster" tabindex="-1">DNS Central Proxy in Garden Runtime Cluster <a class="header-anchor" href="#dns-central-proxy-in-garden-runtime-cluster" aria-label="Permalink to &quot;DNS Central Proxy in Garden Runtime Cluster&quot;">​</a></h4><ul><li>centralised access to zone of landscape&#39;s default domain to avoid load for synchronisation for each seed</li></ul><h3 id="new-architecture" tabindex="-1">New Architecture <a class="header-anchor" href="#new-architecture" aria-label="Permalink to &quot;New Architecture&quot;">​</a></h3><img src="'+l+'" alt="New Architecture" width="500"><h4 id="dns-controller-manager-in-control-plane-shoot-dns-service-deployment-1" tabindex="-1">DNS Controller Manager in control plane (&quot;shoot-dns-service&quot; deployment) <a class="header-anchor" href="#dns-controller-manager-in-control-plane-shoot-dns-service-deployment-1" aria-label="Permalink to &quot;DNS Controller Manager in control plane (&quot;shoot-dns-service&quot; deployment)&quot;">​</a></h4><p>Distributed share nothing <code>dns-controller-manager-nextgeneration</code> deployments per control plane namespace</p><ul><li>Manages DNSProviders and DNSEntries for its namespace only</li><li>DNSProvider with same credentials map to same &quot;account&quot;</li><li><strong>NO</strong> caching/sync of zone state</li><li><strong>NO</strong> read operations per API (if authoritative DNS server reachable)</li><li>uses DNS queries to authoritative DNS servers during reconciliation to decide if any changes need to be written (short-time cached according to TTL of query results)</li><li>same source controllers logic as for old dns-controller-manager</li></ul><h2 id="co-existence-strategy-during-migration-phase" tabindex="-1">Co-existence Strategy During Migration Phase <a class="header-anchor" href="#co-existence-strategy-during-migration-phase" aria-label="Permalink to &quot;Co-existence Strategy During Migration Phase&quot;">​</a></h2><p>To ensure a smooth transition from the old <code>dns-controller-manager</code> to the next generation version, both controllers can run simultaneously within the same seed. This co-existence strategy allows for gradual migration of shoot clusters to have early feedback on the new implementation while still relying on the stable old controller.</p><p>As the old architecture involves a central <code>dns-controller-manager</code> in the seed that manages all <code>DNSProvider</code> and <code>DNSEntries</code> resources for all shoot clusters normally, the migration strategy involves the introduction of a second DNS class. The old controller continues to manage resources without an annotation <code>dns.gardener.cloud/class</code> (or explicit default class <code>dns.gardener.cloud/class=gardendns</code>). To enable the next-generation controller, the <code>providerConfig</code> of the <code>shoot-dns-service</code> extension in the shoot manifest must have the field <code>useNextGenerationController: true</code>. In this case, the shoot-dns-service extension will deploy the new controller with target class <code>gardendns-next-gen</code>. All <code>DNSProvider</code> and <code>DNSEntry</code> resources created by the shoot-dns-service extension or the new controller will then have the annotation <code>dns.gardener.cloud/class=gardendns-next-gen</code> using a special migration mode. Existing resources are updated in-place.</p><p>From the end-user perspective, this migration is transparent.</p><h3 id="back-migration" tabindex="-1">Back migration <a class="header-anchor" href="#back-migration" aria-label="Permalink to &quot;Back migration&quot;">​</a></h3><p>If the field <code>useNextGenerationController</code> is set to <code>false</code> again, the class annotations will be removed from all <code>DNSProvider</code> and <code>DNSEntry</code> resources. The <code>DNSProvider</code> managed by the shoot-dns-service extension will be updated in-place. The <code>DNSEntry</code> and <code>DNSProvider</code> resources managed by the dns-controller-manager deployment named <code>shoot-dns-service</code> are updated in-place as well. This uses a feature of the old controller to allow multiple target classes. By specifying <code>gardendns,gardendns-next-gen</code> as target classes, the old controller will manage resources of both classes and uses the first one on the resources.</p>',29)]))}const x=t(c,[["render",d]]);export{v as __pageData,x as default};
